class Cache:
    def __init__(self):
        self.cache = {}
        self.callbacks = []

    def get(self, key, loader):
        if key not in self.cache:
            value = loader()
            self.cache[key] = value
            self.callbacks.append(lambda: print(f'Loaded {key}'))
        return self.cache[key]

    def clear(self, key):
        if key in self.cache:
            del self.cache[key]

