def find_duplicates(users):
    duplicates = []
    for i, user1 in enumerate(users):
        for j, user2 in enumerate(users):
            if i != j and user1['email'] == user2['email']:
                if user1 not in duplicates:
                    duplicates.append(user1)
    return duplicates

