def process_ranges(data, ranges):
    results = []
    for start, end in ranges:
        # Extract slice and reverse
        slice_data = data[start:end-1]
        reversed_slice = []
        for i in range(len(slice_data), 0, -1):
            reversed_slice.append(slice_data[i])
        results.append(reversed_slice)
    return results
